CREATE SCHEMA IF NOT EXISTS elite_diary;
REVOKE ALL ON SCHEMA elite_diary FROM PUBLIC, anon, authenticated;
SET search_path=elite_diary,public;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL CHECK(jsonb_typeof(value::jsonb) IS NOT NULL));
INSERT INTO settings VALUES(1,'{"name":"Elite Scholars School","timezone":"UTC","address":"","contact":"","session":"","allowSelfApproval":false,"submissionTime":"16:00","reviewTime":"18:00","retentionDays":365,"templateVersion":1,"requiredFields":["topic","todays_lesson","learning_objectives"]}') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('super_admin','school_admin','coordinator','head_teacher','teacher')), permissions TEXT NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(permissions::jsonb) IS NOT NULL), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS academics(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('session','department','class','section','subject')), name TEXT NOT NULL, parent_id TEXT REFERENCES academics(id), start_date TEXT, end_date TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(kind,name,parent_id));
CREATE TABLE IF NOT EXISTS coordinator_heads(coordinator_id TEXT NOT NULL REFERENCES users(id), head_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(coordinator_id,head_id), CHECK(coordinator_id<>head_id));
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id), head_id TEXT NOT NULL REFERENCES users(id), section_id TEXT NOT NULL REFERENCES academics(id), subject_id TEXT NOT NULL REFERENCES academics(id), session_id TEXT NOT NULL REFERENCES academics(id), start_date TEXT NOT NULL, end_date TEXT NOT NULL, weekdays TEXT NOT NULL CHECK(jsonb_typeof(weekdays::jsonb) IS NOT NULL), periods TEXT NOT NULL CHECK(jsonb_typeof(periods::jsonb) IS NOT NULL), due_time TEXT NOT NULL, review_time TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, CHECK(start_date<=end_date));
CREATE TABLE IF NOT EXISTS calendar_exceptions(id TEXT PRIMARY KEY, date TEXT NOT NULL, assignment_id TEXT REFERENCES assignments(id), reason TEXT NOT NULL, UNIQUE(date,assignment_id));
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY, text TEXT NOT NULL, language TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN('ltr','rtl')), active INTEGER NOT NULL DEFAULT 1, scope_id TEXT REFERENCES users(id), created_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quote_schedules(id TEXT PRIMARY KEY, quote_id TEXT NOT NULL REFERENCES quotes(id), date TEXT NOT NULL, scope_id TEXT REFERENCES users(id), priority INTEGER NOT NULL DEFAULT 0, UNIQUE(quote_id,date,scope_id));
CREATE TABLE IF NOT EXISTS diaries(id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), teacher_id TEXT NOT NULL REFERENCES users(id), reviewer_id TEXT NOT NULL REFERENCES users(id), diary_date TEXT NOT NULL, period INTEGER NOT NULL CHECK(period>0), status TEXT NOT NULL CHECK(status IN('draft','submitted','under_review','returned','resubmitted','approved')), version INTEGER NOT NULL DEFAULT 1, content TEXT NOT NULL CHECK(jsonb_typeof(content::jsonb) IS NOT NULL), quote_snapshot TEXT NOT NULL CHECK(jsonb_typeof(quote_snapshot::jsonb) IS NOT NULL), template_snapshot TEXT NOT NULL CHECK(jsonb_typeof(template_snapshot::jsonb) IS NOT NULL), submitted_at TEXT, reviewed_at TEXT, reviewed_by TEXT REFERENCES users(id), review_remarks TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(assignment_id,diary_date,period));
CREATE TABLE IF NOT EXISTS diary_versions(id TEXT PRIMARY KEY, diary_id TEXT NOT NULL REFERENCES diaries(id), version INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', snapshot TEXT NOT NULL CHECK(jsonb_typeof(snapshot::jsonb) IS NOT NULL), created_at TEXT NOT NULL, UNIQUE(diary_id,version));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, diary_id TEXT NOT NULL REFERENCES diaries(id), actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, remarks TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY, diary_id TEXT NOT NULL REFERENCES diaries(id), uploader_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>0), checksum TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), diary_id TEXT REFERENCES diaries(id), message TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, read_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, resource_id TEXT, details TEXT NOT NULL CHECK(jsonb_typeof(details::jsonb) IS NOT NULL), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS template_versions(version INTEGER PRIMARY KEY, actor_id TEXT REFERENCES users(id), snapshot TEXT NOT NULL CHECK(jsonb_typeof(snapshot::jsonb) IS NOT NULL), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS diary_teacher_date ON diaries(teacher_id,diary_date);
CREATE INDEX IF NOT EXISTS diary_status_date ON diaries(status,diary_date);
CREATE INDEX IF NOT EXISTS assignments_teacher ON assignments(teacher_id,active);
CREATE INDEX IF NOT EXISTS assignments_head ON assignments(head_id,active);
CREATE INDEX IF NOT EXISTS notifications_recipient ON notifications(user_id,read_at,created_at);
CREATE INDEX IF NOT EXISTS audit_resource ON audit(resource_id,created_at);
INSERT INTO migrations VALUES(1,to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS assignment_state_events(id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id), effective_date TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN(0,1)), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assignment_events_date ON assignment_state_events(assignment_id,effective_date,created_at);
INSERT INTO migrations VALUES(2,to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;

CREATE OR REPLACE FUNCTION elite_diary.prevent_history_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
REVOKE ALL ON FUNCTION elite_diary.prevent_history_mutation() FROM PUBLIC;
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.diary_versions;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.diary_versions FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.reviews;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.reviews FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.audit;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.audit FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
DROP TRIGGER IF EXISTS immutable_history ON elite_diary.template_versions;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON elite_diary.template_versions FOR EACH ROW EXECUTE FUNCTION elite_diary.prevent_history_mutation();
